import{_ as s,H as e,f as t,i as n}from"./chunks/framework.CBmkDW73.js";const h=JSON.parse('{"title":"Design（設計）","description":"","frontmatter":{},"headers":[],"relativePath":"ja/skills/design.md","filePath":"ja/skills/design.md"}'),i={name:"ja/skills/design.md"};function l(o,a,p,d,c,r){return e(),t("div",null,[...a[0]||(a[0]=[n(`<h1 id="design-設計" tabindex="-1">Design（設計） <a class="header-anchor" href="#design-設計" aria-label="Permalink to &quot;Design（設計）&quot;">​</a></h1><p><strong>Gate：</strong> ユーザーが仕様を承認するまでコードなし。</p><p>何を作るかわかるまで、一度に一つずつ質問する。2〜3つのアプローチとトレードオフを提案し、一つを推薦する。その後、仕様を書く。</p><h2 id="仕様-決定事項のリスト" tabindex="-1">仕様 = 決定事項のリスト <a class="header-anchor" href="#仕様-決定事項のリスト" aria-label="Permalink to &quot;仕様 = 決定事項のリスト&quot;">​</a></h2><p>仕様はこの変更の未解決の質問に答える。典型的なもの：</p><ul><li>契約 / インターフェース？</li><li>データ形状？</li><li>失敗モード？</li><li>スコープ外？</li><li>何のテストがそれを証明するか？</li><li>アーキテクチャ？</li></ul><p>慣用的に仕様を書く。</p><p><strong>質問なし → セクションなし</strong>。Risks / Non-goalsが空なら埋めない。</p><p>宣言を使い、物語を使わない：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>contract:  &lt;インターフェース&gt;</span></span>
<span class="line"><span>invariant: &lt;何が成立しなければならないか&gt;</span></span>
<span class="line"><span>test:      &lt;どうわかるか&gt;</span></span>
<span class="line"><span>deferred:  &lt;今は決めない&gt;</span></span></code></pre></div><p>コードはパスで参照し、貼り付けない。</p><p>引き渡し前に、実装に影響する決定だけを閉じる：契約、データ、失敗、テスト。未解決の <code>Working notes</code> は決定、<code>deferred</code>、または質問になる。</p><h2 id="_2層、1ファイル-docs-staging-specs-yyyy-mm-dd-topic-md" tabindex="-1">2層、1ファイル：<code>docs/staging/specs/YYYY-MM-DD-&lt;topic&gt;.md</code> <a class="header-anchor" href="#_2層、1ファイル-docs-staging-specs-yyyy-mm-dd-topic-md" aria-label="Permalink to &quot;2層、1ファイル：\`docs/staging/specs/YYYY-MM-DD-&lt;topic&gt;.md\`&quot;">​</a></h2><ul><li>上部：決定、契約、不変条件（永続的）。</li><li><code>## Working notes</code>：草案、未解決の質問（<code>ship</code> 時に削除）。</li></ul><h2 id="roadmap-スコープが≥3マイルストーンにわたる場合" tabindex="-1">Roadmap（スコープが≥3マイルストーンにわたる場合） <a class="header-anchor" href="#roadmap-スコープが≥3マイルストーンにわたる場合" aria-label="Permalink to &quot;Roadmap（スコープが≥3マイルストーンにわたる場合）&quot;">​</a></h2><p>一度に全部計画できないほど大きい場合、仕様に <code>## Roadmap</code> を追加：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>## Roadmap</span></span>
<span class="line"><span>- [ ] M1: &lt;一行ゴール&gt;  ← 今詳細に計画</span></span>
<span class="line"><span>- [ ] M2: &lt;一行ゴール&gt;  ← stub</span></span>
<span class="line"><span>- [ ] M3: &lt;一行ゴール&gt;  ← stub</span></span></code></pre></div><p>マーカーは必須。現在のマイルストーンに <code>← 今詳細に計画</code>、他はすべて <code>← stub</code>。スタブは意図であり約束ではない。展開前に更新する。</p><h2 id="gate" tabindex="-1">Gate <a class="header-anchor" href="#gate" aria-label="Permalink to &quot;Gate&quot;">​</a></h2><p><code>docs/staging/specs/YYYY-MM-DD-&lt;topic&gt;.md</code> がディスク上に存在し、ユーザーが確認した後に <code>plan</code> へ引き渡す。</p><p>2つの出口のいずれか：</p><ul><li><strong>→ design</strong>：方向が解決すべき問題 → <code>plan</code> で詳細なタスクへ。</li><li><strong>→ archive</strong>：方向が知識成果物（リバースエンジニアリング発見、プロトコル仕様）、直接アーカイブ。</li></ul>`,22)])])}const u=s(i,[["render",l]]);export{h as __pageData,u as default};
